function workspaceReportHtml(e){const list=posts(e.id),total=totals(e.id);if(!list.length)return`<div class="empty workspace-report-empty"><i data-lucide="file-bar-chart"></i><h3>No hay datos suficientes para generar reporte</h3><p>Registra publicaciones para crear el reporte de esta campaña.</p><button data-new-workspace-post><i data-lucide="plus"></i>Registrar publicación</button></div>`;const platforms={};list.forEach(p=>{const key=p.platform==="Página web"?"Web":p.platform;platforms[key]??={count:0,views:0};platforms[key].count++;platforms[key].views+=Number(p.views||0)});return`<section class="workspace-report"><article class="workspace-report-event"><img src="${esc(e.image)}" alt=""><div><h3>${esc(e.name)}</h3><span class="workspace-event-state ${status(e).toLowerCase()}">${status(e)}</span><p>${esc(fmtDate(e.start,true))} – ${esc(fmtDate(e.end,true))}</p></div></article><article class="workspace-report-summary"><h3>Resumen general</h3><div>${[["file-text",total.count,"Publicaciones"],["eye",compact(total.views),"Visualizaciones"],["chart-no-axes-column-increasing",compact(total.reach),"Alcance"],["heart",compact(total.likes),"Likes"]].map(([icon,value,label])=>`<span><i data-lucide="${icon}"></i><strong>${value}</strong><small>${label}</small></span>`).join("")}</div></article><section class="workspace-platforms"><h3>Contenido por plataforma</h3><div>${Object.entries(platforms).map(([name,data])=>`<article>${platformMark(name==="Web"?"Página web":name)}<strong>${esc(name)}</strong><b>${data.count}</b><span>publicaci${data.count===1?"ón":"ones"}</span><small><i data-lucide="eye"></i>${compact(data.views)} vistas</small></article>`).join("")}</div></section><section class="workspace-report-detail"><h3>Detalle de publicaciones</h3><div>${list.map(p=>`<article><span class="post-icon">${platformMark(p.platform)}</span><div><h4>${esc(p.title)}</h4><p>${esc(fmtDate(p.publishDate))} · ${esc(p.publishTime||"—")} · ${esc(p.platform)}</p><a href="${esc(p.url)}" target="_blank" rel="noopener">${esc(p.url)}</a></div><div class="workspace-report-stats"><span><i data-lucide="eye"></i>${compact(p.views)}</span><span><i data-lucide="chart-no-axes-column-increasing"></i>${compact(p.reach)}</span><span><i data-lucide="heart"></i>${compact(p.likes)}</span></div></article>`).join("")}</div></section><footer class="workspace-report-actions"><button class="primary" data-copy-report="${esc(e.id)}"><i data-lucide="copy"></i>Copiar</button><button data-share-report="${esc(e.id)}"><i data-lucide="share-2"></i>Compartir</button><button data-export-report="${esc(e.id)}"><i data-lucide="file-down"></i>Exportar PDF</button><p><i data-lucide="info"></i>Incluye todas las métricas y enlaces de la campaña.</p></footer></section>`}
function renderReports(){const events=state.events.filter(e=>{const searchable=`${e.name} ${e.location} ${fmtDate(e.start,true)} ${fmtDate(e.end,true)}`.toLowerCase();return posts(e.id).length&&(reportFilter==="all"||reportStage(e).key===reportFilter)&&(!reportQuery||searchable.includes(reportQuery))}).sort((a,b)=>new Date(b.start)-new Date(a.start));$("#reportEmpty").hidden=events.length>0;$("#reportList").hidden=!events.length;$("#reportList").innerHTML=events.map((e,i)=>`${!i||monthKey(e)!==monthKey(events[i-1])?`<div class="report-month"><h3>${esc(monthLabel(e))}</h3><span>${events.filter(x=>monthKey(x)===monthKey(e)).length} reporte${events.filter(x=>monthKey(x)===monthKey(e)).length===1?"":"s"}</span></div>`:""}${reportHtml(e)}`).join("");$$('[data-report-filter]').forEach(x=>x.classList.toggle("active",x.dataset.reportFilter===reportFilter))}
function openReportPreview(id){const e=event(id),modal=$("#reportPreviewModal");activeEvent=id;$("#reportPreviewTitle").textContent=e.name;$("#reportPreviewMeta").textContent=`${fmtDate(e.start,true)} – ${fmtDate(e.end,true)}`;$("#reportPreviewBody").innerHTML=workspaceReportHtml(e);modal.showModal();window.lucide?.createIcons()}
function taskGroupLabel(date){const today=localDate(),tomorrow=new Date();tomorrow.setDate(tomorrow.getDate()+1);if(date===today)return`HOY · ${fmtDate(`${date}T12:00`,true).toUpperCase()}`;if(date===localDate(tomorrow))return`MAÑANA · ${fmtDate(`${date}T12:00`,true).toUpperCase()}`;return"PRÓXIMOS"}
function renderTasks(){const pending=state.tasks.filter(t=>!t.done),done=state.tasks.filter(t=>t.done);$("#pendingCount").textContent=pending.length;$("#doneCount").textContent=done.length;$("#taskBadge").textContent=pending.length;const mobileBadge=$(".mobile-task-badge");if(mobileBadge){mobileBadge.textContent=pending.length;mobileBadge.hidden=!pending.length}let list=(taskFilter==="pending"?pending:done).filter(t=>{const e=event(t.eventId),text=`${t.title} ${t.platform} ${e?.name||""}`.toLowerCase();return(!taskQuery||text.includes(taskQuery))&&(taskEventFilter==="all"||t.eventId===taskEventFilter)&&(taskPlatformFilter==="all"||t.platform===taskPlatformFilter)}).sort((a,b)=>`${a.date}${a.time}`.localeCompare(`${b.date}${b.time}`));let previous="";$("#taskList").innerHTML=list.length?list.map(t=>{const group=taskGroupLabel(t.date),heading=group!==previous?`<h3 class="task-group-title">${esc(group)}</h3>`:"";previous=group;return heading+taskCard(t)}).join(""):`<div class="empty task-empty"><i data-lucide="list-checks"></i><h3>${taskFilter==="pending"?"No tienes tareas pendientes":"Aún no completaste tareas"}</h3>${taskFilter==="pending"?'<button data-add-task><i data-lucide="plus"></i>Crear tarea</button>':""}</div>`;window.lucide?.createIcons()}
function renderProfile(){const p=state.profile||{},name=p.name||"Media Partner",email=p.email||"Sin registrar",country=p.country||"Perú",agency=p.agency||"Independiente",roleLabel=({creator:"Creator",media:"Media Partner",producer:"Productora"})[p.role]||"Creator",initials=name.split(/\s+/).filter(Boolean).slice(0,2).map(x=>x[0]).join("").toUpperCase()||"MP";$("#profileName").textContent=name;$("#profileEmail").textContent=email;$("#profileRole").textContent=roleLabel;$("#profileCountry").textContent=country;$("#profileAvatar").textContent=initials;$("#profileAccountName").textContent=name;$("#profileAccountEmail").textContent=email;$("#profileAgency").textContent=agency;$("#profileAccountCountry").textContent=country;$("#profileNotifications").textContent=p.notifications===false?"Desactivadas":"Activadas";$("#profileLanguage").textContent=p.language||"Español";$("#creatorName").value=p.name||"";$("#creatorEmail").value=p.email||"";$("#creatorAgency").value=p.agency||"";$("#creatorRole").value=p.role||"creator";$("#creatorCountry").value=p.country||"Perú";$("#profileEvents").textContent=state.events.filter(e=>!e.archived).length;$("#profilePosts").textContent=state.posts.length;$("#profileTasks").textContent=state.tasks.filter(t=>t.done).length;$("#profileReports").textContent=state.events.filter(e=>e.reportSentAt).length}
const renderProfileBase=renderProfile;renderProfile=()=>{renderProfileBase();const avatar=$("#profileAvatar"),p=state.profile||{};avatar.textContent=p.avatar?"":avatar.textContent;avatar.style.backgroundImage=p.avatar?`url("${p.avatar}")`:""};
const renderProfileIdentity=renderProfile;renderProfile=()=>{renderProfileIdentity();const p=state.profile||{},pending=p.pendingEmail||"";if(pending){$("#profileEmail").textContent=`${pending} · pendiente`;$("#profileAccountEmail").textContent=`${pending} · pendiente`;$("#creatorEmail").value=pending}};
function render(){renderEvents();renderPlanner();renderReports();renderTasks();renderProfile();$("#taskEvent").innerHTML=state.events.map(e=>`<option value="${esc(e.id)}">${esc(e.name)}</option>`).join("");const taskEventFilterEl=$("#taskEventFilter");if(taskEventFilterEl){const selected=taskEventFilterEl.value||taskEventFilter;taskEventFilterEl.innerHTML=`<option value="all">Todos</option>`+state.events.map(e=>`<option value="${esc(e.id)}">${esc(e.name)}</option>`).join("");taskEventFilterEl.value=selected}window.lucide?.createIcons()}
function switchView(next){view=next;document.body.dataset.view=next;const names={events:"Eventos",planner:"Cronograma",reports:"Reportes",tasks:"Tareas",profile:"Perfil"};$$('[data-view]').forEach(x=>x.classList.toggle("active",x.dataset.view===next));$$('.view').forEach(x=>x.hidden=x.id!==`${next}View`);$("#viewTitle").textContent=names[next];closeSidebar();if(next==="planner")renderPlanner();scrollTo({top:0,behavior:"smooth"})}function closeSidebar(){$("#mediaSidebar").classList.remove("open");$("#sidebarBackdrop").classList.remove("open")}
function openWorkspace(id){activeEvent=id;const e=event(id),eventState=status(e),tone=eventState.toLowerCase(),cover=$("#workspaceCover"),dialog=$("#workspaceModal"),scroll=dialog.querySelector(".workspace-scroll");workspaceDate=e.start.slice(0,10);dialog.classList.remove("workspace-condensed");scroll.scrollTop=0;cover.style.backgroundImage="none";cover.innerHTML=`<div class="workspace-top"><button data-close aria-label="Volver"><i data-lucide="arrow-left"></i></button><div><h2>${esc(e.name)}</h2><p>${esc(fmtDate(e.start,true))} – ${esc(fmtDate(e.end,true))}</p></div><button data-workspace-options aria-label="Opciones"><i data-lucide="more-vertical"></i></button></div><div class="workspace-event-info"><img src="${esc(e.image)}" alt=""><div><span class="workspace-event-state ${tone}">${eventState}</span><p><i data-lucide="map-pin"></i>${esc(e.location)}</p><p><i data-lucide="calendar-days"></i>${esc(fmtDate(e.start))} – ${esc(fmtDate(e.end))}</p></div></div>`;$("#postEventId").value=id;workspaceTab="content";renderWorkspace();dialog.showModal()}
function renderWorkspace(){const e=event(activeEvent),list=posts(activeEvent),total=totals(activeEvent),platforms={Instagram:0,TikTok:0,YouTube:0,Web:0};list.forEach(p=>{const key=p.platform==="Página web"?"Web":p.platform;if(key in platforms)platforms[key]++});$("#workspaceContent .mini-summary").innerHTML=`<article class="content-summary"><header><h3>Resumen de contenido</h3><button data-workspace-tab="report">Ver reporte <i data-lucide="chevron-right"></i></button></header><div class="summary-grid"><div class="summary-total"><strong>${list.length}</strong><span>Publicaciones<br>registradas</span></div><div class="summary-platforms">${Object.entries(platforms).map(([name,count])=>`<span><i data-lucide="${platformIcon(name==="Web"?"Página web":name)}"></i>${name}<b>${count}</b></span>`).join("")}</div><div class="summary-results"><span><i data-lucide="eye"></i><strong>${compact(total.views)}</strong><small>Visualizaciones</small></span><span><i data-lucide="chart-no-axes-column-increasing"></i><strong>${compact(total.reach)}</strong><small>Alcance</small></span></div></div></article>`;$("#workspacePosts").innerHTML=`<div class="publication-heading"><h3>Publicaciones registradas</h3><button data-new-workspace-post><i data-lucide="plus"></i>Nueva publicación</button></div>${list.length?list.map(postCard).join(""):`<div class="empty workspace-post-empty"><i data-lucide="file-plus-2"></i><h3>Aún no tienes contenido registrado</h3><button data-new-workspace-post><i data-lucide="plus"></i>Registrar publicación</button></div>`}`;const eventTasks=tasks(activeEvent);$("#workspaceTasks").innerHTML=workspaceCalendarHtml(e,eventTasks);$("#workspaceReportBody").innerHTML=workspaceReportHtml(e);showWorkspaceTab(workspaceTab);window.lucide?.createIcons()}
