function openEventModal(id=""){closeSidebar();editingEventId=id;const e=id?event(id):null,start=e?new Date(e.start):new Date(Date.now()+2592e6),end=e?new Date(e.end):new Date(start.getTime()+144e5);for(const d of[start,end])d.setMinutes(d.getMinutes()-d.getTimezoneOffset());$("#eventForm").reset();$("#eventModal h2").textContent=e?"Editar evento":"Añadir evento";$("#eventName").value=e?.name||"";$("#eventStart").value=start.toISOString().slice(0,16);$("#eventEnd").value=end.toISOString().slice(0,16);$("#eventLocation").value=e?.location||"";$("#eventTarget").value=e?.target||20;$("#eventImage").value=e?.image||"fan-cochinola.jpg";$("#eventModal").showModal()}function openPostModal(){const modal=$("#postModal");$("#postForm").hidden=false;$("#postEventId").value=activeEvent;$("#postDate").value=localDate();if(!$("#postTime").value)$("#postTime").value="09:30";modal.showModal();setTimeout(()=>$("#postTitle").focus(),0)}function openTaskModal(id=""){closeSidebar();editingTaskId=id;const t=id?state.tasks.find(x=>x.id===id):null;$("#taskForm").reset();$("#taskModal h2").textContent=t?"Editar tarea":"Nueva tarea";$("#taskTitle").value=t?.title||"";$("#taskDate").value=t?.date||workspaceDate||localDate();$("#taskTime").value=t?.time||"09:00";$("#taskPlatform").value=t?.platform||"Instagram";$("#taskPriority").value=t?.priority||"media";$("#taskReminder").value=t?.reminder||"none";$("#taskNotes").value=t?.notes||"";if(t?.eventId)$("#taskEvent").value=t.eventId;else if(activeEvent)$("#taskEvent").value=activeEvent;$("#taskEvent").closest("label").hidden=Boolean($("#workspaceModal").open);$("#taskModal").showModal()}
document.addEventListener("click",async ev=>{const v=ev.target.closest("[data-view]");if(v)return switchView(v.dataset.view);if(ev.target.closest("#menuBtn")){$("#mediaSidebar").classList.add("open");$("#sidebarBackdrop").classList.add("open");return}if(ev.target.closest("#sidebarBackdrop"))return closeSidebar();if(ev.target.closest("[data-add-event]"))return openEventModal();if(ev.target.closest("[data-add-task]"))return openTaskModal();if(ev.target.closest("#quickAdd"))return view==="events"?openEventModal():openTaskModal();const close=ev.target.closest("[data-close]");if(close){ev.preventDefault();close.closest("dialog").close();return}const open=ev.target.closest("[data-open-event]");if(open)return openWorkspace(open.dataset.openEvent);const tab=ev.target.closest("[data-workspace-tab]");if(tab)return showWorkspaceTab(tab.dataset.workspaceTab);if(ev.target.closest("#showPostForm")){$("#postForm").hidden=!$("#postForm").hidden;$("#postDate").value=localDate();return}const filter=ev.target.closest("[data-task-filter]");if(filter){taskFilter=filter.dataset.taskFilter;$$('[data-task-filter]').forEach(x=>x.classList.toggle("active",x===filter));return renderTasks()}const task=ev.target.closest("[data-task]");if(task&&ev.target.closest("[data-toggle-task]")){const t=state.tasks.find(x=>x.id===task.dataset.task);t.done=!t.done;save();render();if($("#workspaceModal").open)renderWorkspace();return}if(task&&ev.target.closest("[data-delete-task]")){state.tasks=state.tasks.filter(x=>x.id!==task.dataset.task);save();render();if($("#workspaceModal").open)renderWorkspace();return}const post=ev.target.closest("[data-post]");if(post&&ev.target.closest("[data-copy-post]")){const p=state.posts.find(x=>x.id===post.dataset.post);return copy(p.url)}if(post&&ev.target.closest("[data-delete-post]")){state.posts=state.posts.filter(x=>x.id!==post.dataset.post);save();render();renderWorkspace();return}const report=ev.target.closest("[data-copy-report]");if(report)return copy(reportText(report.dataset.copyReport));if(ev.target.closest("#copyWorkspaceReport"))return copy(reportText(activeEvent));if(ev.target.closest("#copyAllReports"))return copy(state.events.filter(e=>posts(e.id).length).map(e=>reportText(e.id)).join("\n\n────────\n\n"));if(ev.target.closest("#mediaLogoutBtn")){await fetch("/api/auth/logout",{method:"POST",credentials:"include"}).catch(()=>{});location.href="/login"}});
