document.addEventListener("click",ev=>{if(ev.target.closest("#mobileSearchBtn")){if(view==="tasks"){const search=$("#tasksView .task-search");search.hidden=!search.hidden;if(!search.hidden)$("#taskSearch").focus();return}const search=$(".mobile-search"),input=$("#eventSearch");input.placeholder=view==="reports"?"Buscar reporte por evento, ciudad o fecha":"Buscar eventos";input.value=view==="reports"?reportQuery:eventQuery;search.hidden=!search.hidden;if(!search.hidden)input.focus();return}if(ev.target.closest("#mobileFilterBtn")){if(view==="tasks"){const panel=$("#taskFilterPanel");panel.hidden=!panel.hidden;return}(view==="planner"?$("#plannerFilters"):view==="reports"?$(".report-filters"):$(".event-filters"))?.scrollIntoView({behavior:"smooth",block:"center"});return}if(ev.target.closest("#mobileFab")){if(view==="tasks"||view==="planner"){activeEvent="";openTaskModal();return}const available=state.events.filter(e=>!e.archived);if(!available.length)return openEventModal();$("#quickPostEvent").innerHTML=available.map(e=>`<option value="${esc(e.id)}">${esc(e.name)}</option>`).join("");$("#quickPostModal").showModal();return}if(ev.target.closest("#continueQuickPost")){const id=$("#quickPostEvent").value;if(!id)return;$("#quickPostModal").close();openWorkspace(id);openPostModal();if(quickPostScheduled){$("#postStatus").value="Programado";quickPostScheduled=false}}});

