document.addEventListener("click",ev=>{if(ev.target.closest("[data-new-workspace-post]")||ev.target.closest("#showPostForm")){openPostModal();return}if(ev.target.closest("[data-workspace-options]")){$("#eventOptionsModal").showModal();return}if(ev.target.closest("[data-edit-workspace-event]")){const id=activeEvent;$("#eventOptionsModal").close();openEventModal(id);return}if(ev.target.closest("[data-share-workspace-report]")){$("#eventOptionsModal").close();copy(reportText(activeEvent));return}if(ev.target.closest("[data-archive-workspace-event]")){const e=event(activeEvent);if(e)e.archived=true;save();$("#eventOptionsModal").close();$("#workspaceModal").close();render();notify("Evento archivado");return}const mainView=ev.target.closest("[data-workspace-main-view]");if(mainView){$("#workspaceModal").close();switchView(mainView.dataset.workspaceMainView)}});
