document.addEventListener("DOMContentLoaded",()=>{const planner=$("#plannerView");planner.innerHTML=`<div class="global-planner-head"><div><h2>Mi agenda</h2><p>Todo lo que debes publicar hoy y esta semana.</p></div><div><button data-focus-planner-filters aria-label="Filtrar"><i data-lucide="list-filter"></i></button><button data-add-global-task aria-label="Agregar tarea"><i data-lucide="plus"></i></button></div></div><section class="global-calendar"><header><button data-planner-week="prev" aria-label="Semana anterior"><i data-lucide="chevron-left"></i></button><div><h3 id="plannerMonth"></h3><p id="plannerRange"></p></div><button data-planner-week="next" aria-label="Semana siguiente"><i data-lucide="chevron-right"></i></button></header><div class="global-week" id="weekStrip"></div></section><nav class="planner-filters" id="plannerFilters"><div><button class="active" data-planner-platform="all">Todos</button><button data-planner-platform="Instagram">Instagram</button><button data-planner-platform="TikTok">TikTok</button><button data-planner-platform="YouTube">YouTube</button><button data-planner-platform="Facebook">Facebook</button><button data-planner-platform="Página web">Web</button></div><div><button class="active" data-planner-state="all">Todos los estados</button><button data-planner-state="pending">Pendientes</button><button data-planner-state="done">Completadas</button></div></nav><section class="global-agenda"><header><h3 id="agendaHeading"></h3><span id="agendaCount"></span></header><div class="schedule" id="scheduleList"></div></section><button class="planner-fab" data-add-global-task aria-label="Nueva tarea"><i data-lucide="plus"></i></button>`;document.body.insertAdjacentHTML("beforeend",`<dialog class="event-options-modal agenda-menu" id="agendaMenu"><div><header><strong>Acciones de la tarea</strong><button data-close aria-label="Cerrar"><i data-lucide="x"></i></button></header><button data-agenda-action="edit"><i data-lucide="pencil"></i>Editar</button><button data-agenda-action="date"><i data-lucide="calendar-days"></i>Cambiar fecha</button><button data-agenda-action="time"><i data-lucide="clock-3"></i>Cambiar hora</button><button class="danger" data-agenda-action="delete"><i data-lucide="trash-2"></i>Eliminar</button></div></dialog>`);document.body.dataset.view="events";renderPlanner();window.lucide?.createIcons()});
document.addEventListener("click",ev=>{const date=ev.target.closest("[data-planner-date]");if(date){plannerDate=date.dataset.plannerDate;renderPlanner();return}const weekButton=ev.target.closest("[data-planner-week]");if(weekButton){const d=new Date(`${plannerDate}T12:00`);d.setDate(d.getDate()+(weekButton.dataset.plannerWeek==="next"?7:-7));plannerDate=localDate(d);renderPlanner();return}const platform=ev.target.closest("[data-planner-platform]");if(platform){plannerPlatform=platform.dataset.plannerPlatform;renderPlanner();return}const stateFilter=ev.target.closest("[data-planner-state]");if(stateFilter){plannerState=stateFilter.dataset.plannerState;renderPlanner();return}if(ev.target.closest("[data-focus-planner-filters]")){$("#plannerFilters").scrollIntoView({behavior:"smooth",block:"center"});return}if(ev.target.closest("[data-add-global-task]")){activeEvent="";openTaskModal();return}const eventButton=ev.target.closest("[data-open-agenda-event]");if(eventButton){openWorkspace(eventButton.dataset.openAgendaEvent);return}const post=ev.target.closest("[data-global-post]");if(post&&ev.target.closest("[data-complete-post]")){const p=state.posts.find(x=>x.id===post.dataset.globalPost);if(p)p.status="Publicado";save();render();notify("Publicación completada");return}const menu=ev.target.closest("[data-agenda-menu]");if(menu){activeAgendaTask=menu.dataset.agendaMenu;$("#agendaMenu").showModal();return}const action=ev.target.closest("[data-agenda-action]");if(action){const id=activeAgendaTask,type=action.dataset.agendaAction;$("#agendaMenu").close();if(type==="delete"){pendingDelete={type:"task",id};$("#confirmModal").showModal();return}openTaskModal(id);setTimeout(()=>$(type==="date"?"#taskDate":type==="time"?"#taskTime":"#taskTitle").focus(),0)}});
document.addEventListener("DOMContentLoaded",()=>{
  const shiftWeek=amount=>{const d=new Date(`${plannerDate}T12:00`);d.setDate(d.getDate()+amount);plannerDate=localDate(d);renderPlanner()};
  $$('[data-planner-week]').forEach(button=>button.addEventListener("click",ev=>{ev.stopPropagation();shiftWeek(button.dataset.plannerWeek==="next"?7:-7)}));
  const openGlobalTask=ev=>{ev.stopPropagation();activeEvent="";openTaskModal()};
  $(".global-planner-head [data-add-global-task]")?.addEventListener("click",openGlobalTask);
  $(".planner-fab[data-add-global-task]")?.addEventListener("click",openGlobalTask);
  $("#eventList")?.addEventListener("click",ev=>{
    const card=ev.target.closest("[data-open-event]");
    if(!card)return;
    ev.stopPropagation();
    openWorkspace(card.dataset.openEvent);
  });
  $("#workspaceModal .workspace-tabs")?.addEventListener("click",ev=>{
    const tab=ev.target.closest("[data-workspace-tab]");
    if(!tab)return;
    ev.stopPropagation();
    showWorkspaceTab(tab.dataset.workspaceTab);
  });
  $("#menuBtn")?.addEventListener("click",ev=>{
    ev.stopPropagation();
    $("#mediaSidebar").classList.add("open");
    $("#sidebarBackdrop").classList.add("open");
  });
  $("#sidebarBackdrop")?.addEventListener("click",ev=>{
    ev.stopPropagation();
    closeSidebar();
  });
  $$("#mediaSidebar [data-view]").forEach(button=>button.addEventListener("click",ev=>{
    ev.stopPropagation();
    switchView(button.dataset.view);
  }));
});

document.addEventListener("click",ev=>{
  const eventLink=ev.target.closest("[data-open-task-event]");
  if(eventLink){
    openWorkspace(eventLink.dataset.openTaskEvent);
    showWorkspaceTab("calendar");
    return;
  }
  if(ev.target.closest("[data-task-create-menu]")){
    $("#taskCreateMenu").showModal();
    return;
  }
  if(ev.target.closest("[data-create-task-option]")){
    $("#taskCreateMenu").close();
    activeEvent="";
    openTaskModal();
    return;
  }
  if(ev.target.closest("[data-create-scheduled-post]")){
    $("#taskCreateMenu").close();
    const available=state.events.filter(e=>!e.archived);
    if(!available.length)return openEventModal();
    quickPostScheduled=true;
    $("#quickPostEvent").innerHTML=available.map(e=>`<option value="${esc(e.id)}">${esc(e.name)}</option>`).join("");
    $("#quickPostModal").showModal();
    return;
  }
  if(ev.target.closest("[data-toggle-task-search]")){
    const search=$("#tasksView .task-search");
    search.hidden=!search.hidden;
    if(!search.hidden)$("#taskSearch").focus();
    return;
  }
  if(ev.target.closest("[data-toggle-task-filters]")){
    const panel=$("#taskFilterPanel");
    panel.hidden=!panel.hidden;
  }
});
document.addEventListener("change",ev=>{
  if(ev.target.matches("#taskEventFilter")){
    taskEventFilter=ev.target.value;
    renderTasks();
  }
  if(ev.target.matches("#taskPlatformFilter")){
    taskPlatformFilter=ev.target.value;
    renderTasks();
  }
});

document.addEventListener("click",async ev=>{
  if(ev.target.closest("[data-edit-profile]")){
    renderProfile();
    $("#profileModal").showModal();
    return;
  }
  const setting=ev.target.closest("[data-profile-setting]");
  if(setting){
    const type=setting.dataset.profileSetting;
    if(type==="notifications"){
      state.profile.notifications=state.profile.notifications===false;
      save();
      renderProfile();
      notify(state.profile.notifications===false?"Notificaciones desactivadas":"Notificaciones activadas");
    }else if(type==="language"){
      state.profile.language=state.profile.language==="English"?"Español":"English";
      save();
      renderProfile();
      notify(`Idioma: ${state.profile.language}`);
    }else if(type==="theme")notify("El tema oscuro Festholic está activo");
    else if(type==="security")location.href="/security.html";
    else if(type==="privacy")location.href="/legal.html?section=privacy";
    else notify("Configuración disponible");
    return;
  }
  if(ev.target.closest("#profileLogoutBtn")){
    await fetch("/api/auth/logout",{method:"POST",credentials:"include"}).catch(()=>{});
    location.href="/login";
  }
});
document.addEventListener("change",ev=>{
  if(!ev.target.matches("#creatorAvatar")||!ev.target.files?.[0])return;
  const reader=new FileReader();
  reader.onload=()=>{state.profile.avatar=reader.result;save();renderProfile();notify("Avatar actualizado")};
  reader.readAsDataURL(ev.target.files[0]);
});
document.addEventListener("DOMContentLoaded",()=>{
  $(".profile-identity").insertAdjacentHTML("afterend",`<aside class="profile-incomplete" id="profileIncomplete" hidden><div><strong>Completa tu perfil</strong><small>Agrega tus datos profesionales para identificar tu cuenta.</small></div><button data-edit-profile>Completar información</button></aside>`);
  const updateIncomplete=()=>{$("#profileIncomplete").hidden=Boolean(state.profile?.name&&state.profile?.email&&state.profile?.agency&&state.profile?.country)};
  updateIncomplete();
  $("#profileForm").addEventListener("submit",()=>setTimeout(updateIncomplete,0));
});
document.addEventListener("DOMContentLoaded",hydrateMediaWorkspace);
document.addEventListener("DOMContentLoaded",async()=>{try{const account=await window.FestholicAccount.load();state.profile={...state.profile,name:account.name,email:account.email,pendingEmail:account.pendingEmail||"",avatar:account.avatarUrl||state.profile?.avatar||""};save();renderProfile()}catch(error){console.warn("Account profile",error)}});

